import React, { useEffect } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { RootState, AppDispatch } from '../../store/store';
import { fetchAnalyticsData } from '../../store/slices/analyticsSlice';
import './Analytics.css';

const Analytics: React.FC = () => {
  const dispatch = useDispatch<AppDispatch>();
  const { data, loading, error } = useSelector((state: RootState) => state.analytics);

  useEffect(() => {
    dispatch(fetchAnalyticsData());
  }, [dispatch]);

  if (loading) {
    return (
      <div className="analytics">
        <div className="loading">Loading analytics data...</div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="analytics">
        <div className="error">Error loading analytics: {error}</div>
      </div>
    );
  }

  return (
    <div className="analytics">
      <h1>Trading Analytics</h1>
      
      <div className="analytics-grid">
        <div className="analytics-card">
          <h3>Performance Metrics</h3>
          <div className="metrics-list">
            <div className="metric-row">
              <span>Sharpe Ratio:</span>
              <span>{data?.performanceMetrics?.sharpeRatio?.toFixed(2) || 'N/A'}</span>
            </div>
            <div className="metric-row">
              <span>Max Drawdown:</span>
              <span>{data?.performanceMetrics?.maxDrawdown?.toFixed(2) || 'N/A'}%</span>
            </div>
            <div className="metric-row">
              <span>Profit Factor:</span>
              <span>{data?.performanceMetrics?.profitFactor?.toFixed(2) || 'N/A'}</span>
            </div>
            <div className="metric-row">
              <span>Volatility:</span>
              <span>{data?.performanceMetrics?.volatility?.toFixed(2) || 'N/A'}%</span>
            </div>
          </div>
        </div>

        <div className="analytics-card">
          <h3>Temporal Patterns</h3>
          <div className="temporal-section">
            <h4>Best Trading Hours</h4>
            <div className="pattern-list">
              {data?.temporalPatterns?.bestHours?.length ? (
                data.temporalPatterns.bestHours.map((hour, index) => (
                  <div key={index} className="pattern-item">
                    <span>{hour.hour}:00</span>
                    <span>{hour.winRate?.toFixed(1)}% win rate</span>
                  </div>
                ))
              ) : (
                <div className="no-data">No temporal data available</div>
              )}
            </div>
          </div>
          
          <div className="temporal-section">
            <h4>Best Trading Days</h4>
            <div className="pattern-list">
              {data?.temporalPatterns?.bestDays?.length ? (
                data.temporalPatterns.bestDays.map((day, index) => (
                  <div key={index} className="pattern-item">
                    <span>{day.dayName}</span>
                    <span>{day.avgProfit?.toFixed(2)} avg P&L</span>
                  </div>
                ))
              ) : (
                <div className="no-data">No temporal data available</div>
              )}
            </div>
          </div>
        </div>

        <div className="analytics-card full-width">
          <h3>Account Comparison</h3>
          <div className="comparison-table">
            <div className="table-header">
              <span>Account</span>
              <span>Symbol</span>
              <span>Total Trades</span>
              <span>Win Rate</span>
              <span>Total P&L</span>
              <span>Sharpe Ratio</span>
            </div>
            {data?.accountComparison?.length ? (
              data.accountComparison.map((account, index) => (
                <div key={index} className="table-row">
                  <span>{account.accountName}</span>
                  <span>{account.symbol}</span>
                  <span>{account.totalTrades}</span>
                  <span>{account.winRate?.toFixed(1)}%</span>
                  <span className={account.totalPnL >= 0 ? 'positive' : 'negative'}>
                    ${account.totalPnL?.toFixed(2)}
                  </span>
                  <span>{account.sharpeRatio?.toFixed(2) || 'N/A'}</span>
                </div>
              ))
            ) : (
              <div className="no-data">No account data available</div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Analytics;
